#!/usr/bin/env bash
# Generated by: GPT-6 (Codex)
# 恢复一次安装修改的入口；下载的插件和运行数据继续保留。
set -euo pipefail
source "$(dirname -- "${BASH_SOURCE[0]}")/lib.sh"
if [[ ${1:-} == --list && $# == 1 ]]; then
  for backup in "$DF_STATE"/backups/*; do
    if [[ ! -d $backup ]]; then
      continue
    fi
    state=incomplete
    if [[ -e $backup/complete ]]; then
      state=complete
    fi
    if [[ -e $backup/rolled-back ]]; then
      state=rolled-back
    fi
    printf '%s %s\n' "${backup##*/}" "$state"
  done
  exit
fi
if [[ $# != 1 || $1 == */* || $1 == .* ]]; then
  die 'Usage: scripts/rollback.sh --list | BACKUP_ID'
fi
backup="$DF_STATE/backups/$1"
if [[ ! -f $backup/links.tsv || ! -f $backup/home ]]; then
  die 'Unknown backup.'
fi
if [[ $(cat "$backup/home") != "$DF_HOME" ]]; then
  die 'Backup belongs to another home.'
fi
if [[ -e $backup/rolled-back ]]; then
  die 'This backup has already been restored.'
fi

# 第一遍只检查：任何入口被用户修改，都在执行恢复前停止。
# had=1 表示安装前存在原文件，对应备份必须仍然可用。
while IFS=$'\t' read -r id relative source had; do
  if [[ ! $id =~ ^[0-9]+$ || $relative == /* || $relative == *..* || ! $had =~ ^[01]$ ]]; then
    die 'Invalid backup journal.'
  fi
  target="$DF_HOME/$relative"
  if [[ -L $target && $(readlink -- "$target") == "$source" ]]; then
    [[ $had == 0 || -e $backup/$id || -L $backup/$id ]] || die "Missing original: $target"
  elif [[ ! -e $target && ! -L $target ]]; then
    [[ $had == 0 || -e $backup/$id || -L $backup/$id ]] || die "Missing original: $target"
  elif [[ $had == 1 && ! -e $backup/$id && ! -L $backup/$id && ! -e $backup/$id.linked ]]; then
    # 兼容安装中断：已写清单，但还没有移动原文件。
    continue
  else
    die "Changed since installation: $target; preserve it elsewhere before rollback."
  fi
done < "$backup/links.tsv"

# 第二遍才执行恢复，按安装的反向顺序处理。
# unlink 只删除已确认是本次创建的链接，不删除链接指向的数据。
while IFS=$'\t' read -r id relative source had; do
  target="$DF_HOME/$relative"
  if [[ -L $target && $(readlink -- "$target") == "$source" ]]; then
    unlink -- "$target"
  fi
  if [[ $had == 1 && ( -e $backup/$id || -L $backup/$id ) ]]; then
    mv -- "$backup/$id" "$target"
  fi
done < <(tac "$backup/links.tsv")
touch "$backup/rolled-back"
printf 'Restored links from %s. Plugins, history, caches and local settings retained.\n' "$1"
